import{_ as t,o as r,c as o,ag as d}from"./chunks/framework.cyF4XceO.js";const f=JSON.parse('{"title":"バージョンと互換性","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docs/versions.md","filePath":"ja/docs/versions.md"}'),a={name:"ja/docs/versions.md"};function i(n,e,s,c,l,m){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="バージョンと互換性" tabindex="-1">バージョンと互換性 <a class="header-anchor" href="#バージョンと互換性" aria-label="Permalink to &quot;バージョンと互換性&quot;">​</a></h1><p>Takoform の domain version axes は API/Core release の SemVer と各 Form の <code>definitionVersion</code> の二つです。Provider SemVer、package/schema の ID・digest、 withdrawn lane は artifact / history identity であり、domain axis を増やしません。</p><h2 id="current-identity" tabindex="-1">Current identity <a class="header-anchor" href="#current-identity" aria-label="Permalink to &quot;Current identity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>surface</th><th>identity</th><th>用途</th></tr></thead><tbody><tr><td>API/Core</td><td><strong><code>v1.0.1</code></strong></td><td><code>forms.takoform.com/v1</code> 上の current compatibility checkpoint。互換性のある 1.x は同じ lane に留まります。</td></tr><tr><td>external Edge publication</td><td><a href="https://github.com/tako0614/takoform-forms/commit/3231633605b737ce5279d7fc020b4780568e7091" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3231633605b737ce5279d7fc020b4780568e7091</code></a></td><td>17 content-addressed package の公開正本。</td></tr><tr><td>embedded Edge candidate snapshot</td><td><a href="/forms/candidates/edge.forms.takoform.com/candidate-set.json"><code>forms/candidates/edge.forms.takoform.com/candidate-set.json</code></a></td><td>Provider repository 内の <code>publicationStatus: unpublished</code> snapshot。公開 evidence ではありません。</td></tr><tr><td>Registry Provider</td><td><strong><code>4.0.0</code></strong></td><td>同じ <code>tako0614/takoform</code> addressで publisher set の Edge Form 17種だけを登録 (Provider 3 から引き継ぐ 16種 + <code>ObjectBucket</code>)。Registry 公開済み。</td></tr><tr><td>retained Registry Provider</td><td><strong><code>3.0.0</code></strong></td><td>8 versionless family / 31 mappingのimmutable aggregate history。</td></tr><tr><td>Form Package envelope</td><td><code>packages.forms.takoform.com/v1alpha5</code></td><td>package identity。公開は Provider release と独立します。</td></tr></tbody></table><p>Exact Form は family、kind、<code>definitionVersion</code>、<code>schemaDigest</code> で識別します。 generated resource page は対応する Form Definition に link し、この identity を state に保持します。Provider resource 名は adapter metadata です。</p><h2 id="provider-compatibility-history" tabindex="-1">Provider compatibility history <a class="header-anchor" href="#provider-compatibility-history" aria-label="Permalink to &quot;Provider compatibility history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Host/API lane</th><th>互換性</th></tr></thead><tbody><tr><td><strong>4.0.0</strong></td><td>current Host API</td><td>publisher set の Edge Form 17種限定の現行 Registry 公開 release。</td></tr><tr><td><strong>3.0.0</strong></td><td>current Host API</td><td>8 family / 31 typed mappingのimmutable retained Registry distribution。</td></tr><tr><td><strong>2.1.1</strong></td><td><code>forms.takoform.com/v1beta1</code></td><td><a href="/release/provider-form-identities.json">identity ledger</a> にある 15 immutable Edge Form identity 用の retained client。</td></tr><tr><td><strong>2.0.0</strong></td><td>withdrawn <code>v1alpha2</code> epoch</td><td>不変の Registry history。exact-pin recovery と migration のみ。</td></tr><tr><td><strong>1.0.3</strong></td><td>withdrawn <code>v1alpha1</code> epoch</td><td>不変の Registry history。exact-pin recovery と migration のみ。</td></tr></tbody></table><p>Provider release は Form definition / package publication と独立しています。 withdrawn Provider epoch で作成した state は <a href="/release/migrations/v2-to-v3.html">v2-to-v3 migration boundary</a> を確認してください。Provider 3からProvider 4へ進む前には <a href="/release/migrations/v3-to-v4.html">v3-to-v4 publisher-set boundary</a>を確認してください。 自動 migration はありません。</p><h2 id="related-reference" tabindex="-1">Related reference <a class="header-anchor" href="#related-reference" aria-label="Permalink to &quot;Related reference&quot;">​</a></h2><ul><li><a href="/ja/docs/">Provider resource reference</a></li><li><a href="/forms/">Provider mapping inventory</a></li><li><a href="/release/">Specification and release evidence</a></li><li><a href="/conformance/">Conformance evidence</a></li></ul>',10)])])}const p=t(a,[["render",i]]);export{f as __pageData,p as default};
